CREATE TABLE geofences (id UUID PRIMARY KEY, name VARCHAR(120) NOT NULL, latitude DOUBLE PRECISION NOT NULL, longitude DOUBLE PRECISION NOT NULL, radius_meters DOUBLE PRECISION NOT NULL CHECK (radius_meters > 0), active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE sos_alerts (id UUID PRIMARY KEY, user_id UUID NOT NULL REFERENCES users(id), latitude DOUBLE PRECISION, longitude DOUBLE PRECISION, message VARCHAR(500), status VARCHAR(30) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, resolved_at TIMESTAMPTZ);
CREATE TABLE notifications (id UUID PRIMARY KEY, user_id UUID REFERENCES users(id) ON DELETE CASCADE, title VARCHAR(160) NOT NULL, message VARCHAR(500) NOT NULL, severity VARCHAR(30) NOT NULL, read_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE audit_logs (id UUID PRIMARY KEY, actor_id UUID REFERENCES users(id) ON DELETE SET NULL, action VARCHAR(120) NOT NULL, target VARCHAR(180), details VARCHAR(1000), created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_notifications_user_created ON notifications(user_id, created_at DESC);
CREATE INDEX idx_audit_logs_created ON audit_logs(created_at DESC);
